create role anon;
create role authenticated;
create schema auth;
create table auth.users (id uuid primary key);
create function auth.uid() returns uuid language sql stable as
  $$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
grant usage on schema public, auth to anon, authenticated;
create table public.athlete_measurements (id uuid not null default gen_random_uuid(), athlete_id uuid, plan_id uuid, source_plan_key text not null default ''::text, client_key text not null, measurement_date date not null, week_number integer, waga numeric, udo numeric, dupa numeric, brzuch numeric, klatka numeric, biceps numeric, szyja numeric, source text not null default 'monkeypanel'::text, raw_payload jsonb not null default '{}'::jsonb, recorded_at timestamp with time zone, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
create table public.athletes (id uuid not null default gen_random_uuid(), client_key text not null, name text not null, status text not null default 'active'::text, notes text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
create table public.exercise_aliases (id uuid not null default gen_random_uuid(), exercise_id uuid not null, alias text not null, normalized_alias text generated always as (lower(regexp_replace(alias, '[^[:alnum:]]+'::text, ' '::text, 'g'::text))) stored, created_at timestamp with time zone not null default now());
create table public.exercises (id uuid not null default gen_random_uuid(), name text not null, youtube_url text, notes text, default_mode text not null default 'sets'::text, default_category text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), archived_at timestamp with time zone, archived_reason text);
