create table public.plan_resources (id uuid not null default gen_random_uuid(), plan_id uuid not null, label text not null, url text, resource_type text not null default 'video'::text, notes text, source_sheet text, source_cell text, created_at timestamp with time zone not null default now());
create table public.plans (id uuid not null default gen_random_uuid(), slug text not null, name text not null, start_date date not null, weeks integer not null, status text not null default 'draft'::text, notes text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), import_id uuid, source_format text, imported_at timestamp with time zone, published_at timestamp with time zone);
