create table public.progression_sets (id uuid not null default gen_random_uuid(), progression_exercise_id uuid not null, week_number integer not null, set_no integer not null, label text not null default 'Seria'::text, reps_text text, kg numeric(7,2), notes text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), raw_text text, load_text text, set_count integer, is_skip boolean not null default false, is_deload boolean not null default false, source_sheet text, source_cell text, prescription jsonb not null default '{}'::jsonb, rest_text text);
